INSERT INTO `sys_oper_log` VALUES (343, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_54791b52-aeb4-4457-a6bc-56ceb380a4df_1032x1280.png_width256.webp\",\"backWeId\":\"10000353106\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:45:24\",\"delFlag\":\"0\",\"id\":50,\"name\":\"bsd51\",\"params\":{},\"promot\":\"在这张图片中，模特站在一片被阳光照耀的雪地上，背景是清晰的蓝天和茂密的松树林。她身体微微侧向镜头，头部略微倾斜，展现出一种自然且自信的姿态。她的右手抬起，轻轻搭在脸颊附近，手指自然弯曲，仿佛在调整或轻触脸部，动作优雅而从容。整体姿态显得轻松、惬意，透露出一种享受当下环境的愉悦感。她的视线朝向镜头方向，嘴角带着微笑，流露出温暖与亲切的神情。整个姿态既展现了她在户外活动中的自在，也传递出一种时尚与活力并存的氛围。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:57:35\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:57:35', 5);
INSERT INTO `sys_oper_log` VALUES (344, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_63ceb80b-026d-41db-9e36-8d4e5287eb4e_896x1200.png_width256.webp\",\"backWeId\":\"10000353110\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:46:33\",\"delFlag\":\"0\",\"id\":51,\"name\":\"bsd52\",\"params\":{},\"promot\":\"模特站在雪地里，身体微微侧向画面左侧，头部略微转向镜头，展现出一种自信而从容的姿态。她的双臂自然下垂，左手则搭在身侧的白色毛绒外套上，仿佛正准备将其披上或刚刚脱下。她的站姿稳健，双腿微分，呈现出一种轻松而优雅的平衡感。整体姿态透露出一种时尚与自然融合的氛围，既展现了她在寒冷环境中的从容，又突显了她对造型的掌控力。背景中连绵的雪山与蓝天相映成趣，进一步衬托出她挺拔而充满活力的身形。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:57:46\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:57:46', 6);
INSERT INTO `sys_oper_log` VALUES (345, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_4d7f026e-8fac-4b79-8670-e8eb93311eed_736x976.png_width256.webp\",\"backWeId\":\"10000353112\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:47:03\",\"delFlag\":\"0\",\"id\":52,\"name\":\"bsd53\",\"params\":{},\"promot\":\"在这张图片中，模特站在一片广阔的雪地上，背景是连绵起伏的山脉和晴朗的蓝天。她身体微微侧向镜头，呈现出一种自然且自信的姿态。她的右手抬起，手指轻轻扶在护目镜上方，似乎是在调整或遮挡阳光，动作轻盈而优雅。左手自然垂下，略微弯曲，显得放松而从容。她的头部微微倾斜，目光朝向一侧，展现出一种专注而又略带俏皮的神情。整体姿态既充满活力又不失优雅，体现出她在户外环境中的自在与享受。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:57:53\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:57:53', 6);
INSERT INTO `sys_oper_log` VALUES (346, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_c37e2518-e21f-494d-bc48-d3f42881a592_1024x1280.png_width256.webp\",\"backWeId\":\"10000353115\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:47:29\",\"delFlag\":\"0\",\"id\":53,\"name\":\"bsd54\",\"params\":{},\"promot\":\"在这张图片中，模特站在雪中的街道上，姿态自然优雅。她微微侧身面向镜头，头部略向一侧倾斜，眼神温柔地注视着前方，嘴角带着淡淡的微笑，流露出一种宁静而温暖的神情。她的身体略微前倾，右手握着透明雨伞的把手，伞面覆盖在头顶上方，遮挡了飘落的雪花。左手自然垂下，整体动作显得从容不迫。背景是被白雪覆盖的城市街景，树木和地面都积满了雪，营造出一种静谧的冬日氛围。模特的姿态与周围环境融为一体，展现出一种与自然和谐共处的美感。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:58:02\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:58:02', 6);
INSERT INTO `sys_oper_log` VALUES (347, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_c563d5a2-0a3c-4bbf-9f9e-d1cfef59cff9_1080x1344.png_width256.webp\",\"backWeId\":\"10000353116\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:47:54\",\"delFlag\":\"0\",\"id\":54,\"name\":\"bsd55\",\"params\":{},\"promot\":\"模特站在雪地上，背对镜头微微侧身，身体略微向左倾斜，头部转向镜头方向，目光直视前方。她的姿态自然优雅，展现出一种自信与从容的气质。双臂自然下垂，右手轻轻搭在身侧，左手则自然地放在身体后方，整体动作流畅且富有张力。她站立的位置略高于周围的雪地，形成一种居高临下的视觉效果，增强了画面的层次感。背景是连绵的雪山和晴朗的蓝天，衬托出她挺拔的身形和坚定的姿态。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:58:08\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:58:08', 4);
INSERT INTO `sys_oper_log` VALUES (348, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_81280f65-0da5-4a5c-a47a-f7cb0200085d_960x1280.png_width256.webp\",\"backWeId\":\"10000353117\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:48:20\",\"delFlag\":\"0\",\"id\":55,\"name\":\"bsd56\",\"params\":{},\"promot\":\"在这张图片中，模特以一种自然且略带沉静的姿态坐在雪地上。她的身体微微前倾，双腿并拢，呈现出一种放松但不失优雅的坐姿。她的双手自然地放在膝盖上，手臂略微弯曲，整体姿态显得从容而稳重。头部微微抬起，目光直视镜头，表情柔和，透露出一种宁静与专注的神情。背景中的冰雪环境与她的姿态相得益彰，营造出一种与自然和谐共处的氛围。她似乎在静静地欣赏周围的景色，又仿佛在与观者进行无声的交流，整个画面充满了静谧与美感。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:58:16\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:58:16', 6);
INSERT INTO `sys_oper_log` VALUES (349, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_719f18a1-60aa-4fff-8655-10b7a3d50696_736x1304.png_width256.webp\",\"backWeId\":\"10000353118\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:48:43\",\"delFlag\":\"0\",\"id\":56,\"name\":\"bsd57\",\"params\":{},\"promot\":\"在这张图片中，模特站在一片雪地上，背景是被白雪覆盖的山坡和几栋阿尔卑斯风格的建筑。她的姿态自然且充满自信：身体微微侧向镜头，左腿略微向前伸展，右腿稍后，形成一种平衡而优雅的站姿。她的双臂自然下垂，左手轻轻提着一个滑雪头盔，右手则自然地放在身侧。整体姿势展现出一种轻松自在又不失时尚感的氛围，仿佛正准备开始一场滑雪之旅。她的面部朝向镜头，面带微笑，眼神明亮，传递出愉悦和活力的情绪。整个姿态与周围的冬季雪景完美融合，突显出一种动感与静谧并存的美感。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:58:23\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:58:23', 6);
INSERT INTO `sys_oper_log` VALUES (350, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_7f047fde-8587-4c3d-a588-6426657496f7_1080x1344.png_width256.webp\",\"backWeId\":\"10000353120\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:49:57\",\"delFlag\":\"0\",\"id\":57,\"name\":\"bsd58\",\"params\":{},\"promot\":\"在这张图片中，模特站在一片被白雪覆盖的宁静环境中，姿态自然优雅。她微微侧身，面向画面左侧，头略微抬起，目光温柔地望向远方，似乎在欣赏雪中的景色或沉浸在某种思绪之中。她的右手轻轻握着一把撑开的黑色雨伞，伞面上积满了厚厚的白雪，显得格外纯净。左手则自然地放在胸前，微微举起，仿佛在感受飘落的雪花。整体姿态轻松而富有诗意，流露出一种静谧与从容的氛围。她的身体微微前倾，展现出一种轻盈而柔美的动态感，与周围雪景相得益彰，营造出一种梦幻般的冬日意境。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:58:30\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:58:30', 5);
INSERT INTO `sys_oper_log` VALUES (351, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_293c32c7-c05b-44a1-a67d-bfe5139a51d4_1024x1280.png_width256.webp\",\"backWeId\":\"10000353121\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:50:22\",\"delFlag\":\"0\",\"id\":58,\"name\":\"bsd59\",\"params\":{},\"promot\":\"在这张图片中，模特站在一座被白雪覆盖的木屋前，背景是冬季森林的宁静景象。她身体微微前倾，双手合拢于嘴前，仿佛正在吹出一口气，或是准备接住飘落的雪花。她的姿态显得轻盈而自然，流露出一种与冬日环境互动的温柔感。双臂略微弯曲，手部动作细腻，表现出一种专注而略带俏皮的情绪。整体姿态传达出一种沉浸于雪景中的愉悦与宁静，仿佛在享受这片刻的冬日浪漫。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:58:39\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:58:39', 6);
INSERT INTO `sys_oper_log` VALUES (352, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_7e876038-9e62-4849-b6ab-f365b0b2d315_1024x1280.png_width256.webp\",\"backWeId\":\"10000353122\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:50:46\",\"delFlag\":\"0\",\"id\":59,\"name\":\"bsd60\",\"params\":{},\"promot\":\"模特以盘腿坐姿坐在雪地上，身体微微前倾，双膝并拢，双脚自然交叉置于身前。双手轻轻放在膝盖上，手指自然放松，呈现出一种从容而舒适的姿态。她的头部略微侧向一侧，面带微笑，目光看向镜头方向，整体姿态显得轻松愉悦且富有亲和力。背景中的雪地与建筑形成对比，突显出她稳重而优雅的坐姿，营造出宁静和谐的氛围。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:58:49\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:58:49', 5);
INSERT INTO `sys_oper_log` VALUES (353, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_ba6ada33-f802-4fbd-92ef-4eefff04a150_600x952.png_width256.webp\",\"backWeId\":\"10000353123\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:51:09\",\"delFlag\":\"0\",\"id\":60,\"name\":\"bsd61\",\"params\":{},\"promot\":\"模特站立在雪地上，身体略微向一侧倾斜，呈现出一种自然且优雅的姿势。她的双手抬起，轻轻扶住外套的毛领部分，动作显得从容而自信。头部微微侧转，目光直视镜头，展现出一种沉稳而专注的神情。双腿自然分开，站姿稳健，重心均匀分布，体现出良好的平衡感和姿态控制。整体姿态既展现了她在雪山环境中的从容不迫，又流露出一种时尚与力量并存的气质。背景是广阔的雪山和晴朗的蓝天，进一步衬托出她挺拔而坚定的身影。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:58:56\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:58:56', 5);
INSERT INTO `sys_oper_log` VALUES (354, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_51170791-c73d-43de-8c17-293f0258255a_824x1032.png_width256.webp\",\"backWeId\":\"10000353124\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:51:34\",\"delFlag\":\"0\",\"id\":61,\"name\":\"bsd62\",\"params\":{},\"promot\":\"在这张图片中，模特站立在雪地背景前，姿态优雅而自信。她身体微微侧向镜头，右臂自然抬起，手轻触头部上方的护目镜，动作显得从容且富有表现力。左臂则稳稳地持着一副滑雪板，滑雪板斜靠在身侧，显示出她与滑雪运动的紧密联系。她的站姿挺拔，双腿略微分开，重心平衡，展现出一种稳健而放松的状态。整体姿态流露出一种从容不迫的运动美感，仿佛正准备开始一次滑雪之旅，同时又不失时尚与魅力。背景中的雪山、松林和木屋为她的姿态增添了自然与宁静的氛围。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:59:06\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:59:06', 5);
INSERT INTO `sys_oper_log` VALUES (355, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_da5e1ad1-2d02-42cd-a3f4-8ad8a7f55955_736x1304.png_width256.webp\",\"backWeId\":\"10000353125\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:51:56\",\"delFlag\":\"0\",\"id\":62,\"name\":\"bsd63\",\"params\":{},\"promot\":\"在这张图片中，模特以一种充满活力和自由感的姿态呈现。她单膝跪在雪地上，身体微微向一侧倾斜，展现出优雅的曲线。她的左臂高高举起，手掌朝上，仿佛在迎接天空中的夕阳，而右臂则自然地向一侧伸展，形成一种平衡且富有张力的构图。她的头部轻轻向后仰，闭着眼睛，脸上带着微笑，流露出一种宁静与享受当下的情绪。整体姿态既展现了力量与柔美并存的美感，又传递出与自然融为一体的和谐氛围。背景中，夕阳缓缓沉入地平线，将天空染成温暖的橙粉色，与雪地的冷色调形成鲜明对比，进一步突显了人物动态的视觉焦点。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:59:12\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:59:12', 5);
INSERT INTO `sys_oper_log` VALUES (356, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_bad71b68-a959-45b5-bcfe-c39e78603895_736x920.png_width256.webp\",\"backWeId\":\"10000353126\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:52:23\",\"delFlag\":\"0\",\"id\":63,\"name\":\"bsd64\",\"params\":{},\"promot\":\"模特站在街道中央，身体微微侧向画面右侧，头部略微转向右前方，目光投向远方。她的姿态自然放松，双臂自然垂于身体两侧，肩部线条舒展，呈现出一种静谧而沉思的氛围。她站立的位置恰好位于街道的视觉中心，与远处的富士山形成一条延伸的视线轴线，增强了画面的空间感和纵深感。整体姿态透露出一种宁静、内省的情绪，仿佛在凝视着远方的风景或沉浸在自己的思绪中。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:59:18\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:59:18', 4);
INSERT INTO `sys_oper_log` VALUES (357, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_cd0494e7-0e78-485b-bf77-17c028df0901_1024x1280.png_width256.webp\",\"backWeId\":\"10000353129\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:52:43\",\"delFlag\":\"0\",\"id\":64,\"name\":\"bsd65\",\"params\":{},\"promot\":\"在这张图片中，模特站在雪地上，背景是连绵的雪山和晴朗的蓝天。她的身体微微侧向镜头，呈现出一种自然且自信的姿态。她的一只手插在裤兜里，另一只手自然地垂在身侧，手中拿着滑雪护目镜，显得轻松而从容。她的双腿略微分开，站姿稳健，展现出良好的平衡感和对环境的掌控力。整体姿态既放松又充满活力，传达出一种享受户外运动的愉悦心情。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:59:26\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:59:26', 6);
INSERT INTO `sys_oper_log` VALUES (358, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_c2e06a0f-5f27-4378-8be4-c253ad1049db_1080x1344.png_width256.webp\",\"backWeId\":\"10000353130\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:53:08\",\"delFlag\":\"0\",\"id\":65,\"name\":\"bsd66\",\"params\":{},\"promot\":\"模特站在城市街道的斑马线上，身体略微侧向镜头，呈现出一种自然且放松的姿态。她的重心微微偏向一侧，右腿在前，左腿稍后，形成一种动态平衡感。双臂自然下垂，右手插在羽绒服口袋中，左手则轻搭在身侧，显得随性而优雅。头部微微上扬，目光望向画面的斜上方，流露出一种沉静而自信的神情。整体姿态展现出一种都市女性的从容与时尚感，既不过分刻意，又充满表现力。背景中的城市建筑和行人衬托出她作为画面主体的突出存在感。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:59:34\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:59:34', 7);
INSERT INTO `sys_oper_log` VALUES (359, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_944c3eaf-2505-4eca-a073-6f63a0deedcb_736x976.png_width256.webp\",\"backWeId\":\"10000353131\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:53:38\",\"delFlag\":\"0\",\"id\":66,\"name\":\"bsd67\",\"params\":{},\"promot\":\"在这张图片中，模特正站在一条宽阔的街道中央的斑马线上，背对镜头，面向远处的富士山。她的身体微微侧向画面左侧，双臂自然下垂，右手轻轻握着一个黑色的小物件（可能是相机或手机），左手自然地放在身侧。她的姿态显得从容而优雅，仿佛在静静欣赏眼前壮丽的景色。整个身体线条流畅，展现出一种宁静与和谐的美感。她站立的位置恰好将视线引向远方的富士山，形成了一种人与自然交融的视觉效果。街道两旁的建筑和电线杆整齐排列，延伸至远方，增强了画面的纵深感。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:59:42\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:59:42', 5);
INSERT INTO `sys_oper_log` VALUES (360, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_8a49fa0c-a10f-4a53-880d-e36695c74c71_736x976.png_width256.webp\",\"backWeId\":\"10000353132\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:54:00\",\"delFlag\":\"0\",\"id\":67,\"name\":\"bsd68\",\"params\":{},\"promot\":\"模特站立在铺有灰色石砖的街道上，身体微微侧向镜头，呈现出自然放松的姿态。她的双臂自然垂于身前，双手交叠显得优雅而从容。双腿略微分开，重心均匀分布，展现出一种稳定而自信的站姿。头部微微抬起，面带微笑，目光直视前方，流露出亲切与愉悦的情绪。整体姿态轻松自然，既不失端庄，又带有几分随性与活力，与周围秋日的街景和谐相融。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:59:48\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:59:48', 6);
INSERT INTO `sys_oper_log` VALUES (361, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_41fcb1ce-e738-44e4-8751-c5cf27b353e7_736x920.png_width256.webp\",\"backWeId\":\"10000353133\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:54:20\",\"delFlag\":\"0\",\"id\":68,\"name\":\"bsd69\",\"params\":{},\"promot\":\"模特站在雪地中，身体微微向右侧倾斜，呈现出一种自然、轻松的姿态。她的左腿向前抬起，脚尖轻点地面，仿佛正迈步前行或在调整姿势，展现出一种动态的平衡感。右腿则稳稳地支撑着身体，膝盖略微弯曲，增加了整体姿态的柔和与优雅。双臂自然下垂，左手轻轻搭在身前，右手则放在胸前，手指微曲，显得从容而自信。头部微微侧向镜头，眼神温柔而专注，流露出一种宁静与愉悦的情绪。整个姿态既充满活力又不失优雅，与周围的雪景和木屋环境和谐相融，营造出一种冬日里的温暖与惬意氛围。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 13:59:54\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 13:59:54', 6);
INSERT INTO `sys_oper_log` VALUES (362, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_5f3b2410-7045-4d4b-a6e8-58587f597378_960x1200.png_width256.webp\",\"backWeId\":\"10000353134\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:54:43\",\"delFlag\":\"0\",\"id\":69,\"name\":\"bsd70\",\"params\":{},\"promot\":\"模特站立在雪地中，身体微微侧向画面左侧，头部略微抬起，目光望向左上方，展现出一种优雅而略带沉思的姿态。她的双臂自然交叉于胸前，双手戴着白色针织手套，姿态端庄且富有层次感。整体站姿挺拔，腿部线条修长，双腿并拢，呈现出一种从容自信的气质。背景是被白雪覆盖的地面和常绿树木，与她的姿态形成和谐的视觉平衡，突显出静谧而清冷的冬日氛围。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 14:00:01\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 14:00:01', 5);
INSERT INTO `sys_oper_log` VALUES (363, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_e32dc554-45c9-45cd-a7c3-85633db41bf5_1048x1280.png_width256.webp\",\"backWeId\":\"10000353135\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:55:06\",\"delFlag\":\"0\",\"id\":70,\"name\":\"bsd71\",\"params\":{},\"promot\":\"在这张图片中，模特站立在一片被白雪覆盖的开阔地带，背景是雄伟壮丽的雪山和稀疏的树木。她的身体微微前倾，双脚自然分开，站姿显得自信而放松。她双臂自然垂于身体两侧，略微向外展开，展现出一种从容的姿态。头部微微抬起，目光直视前方，似乎在与镜头进行交流。整体姿态透露出一种优雅与沉稳，与周围的自然景观形成和谐的呼应。阳光从上方照射下来，在雪地上投下清晰的影子，进一步突显了她挺拔的身形和坚定的站姿。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 14:00:09\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 14:00:09', 4);
INSERT INTO `sys_oper_log` VALUES (364, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_d8c6c45e-45df-4e54-a91f-be4d43d8b2a7_736x976.png_width256.webp\",\"backWeId\":\"10000353136\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:55:28\",\"delFlag\":\"0\",\"id\":71,\"name\":\"bsd72\",\"params\":{},\"promot\":\"模特站在雪地中央，身体微微前倾，展现出一种自信而从容的姿态。她的双臂自然下垂，左手自然放松在身侧，手指微微弯曲，显得优雅而不失随性。双腿略微分开，站姿稳健，重心均匀分布在双脚之间，呈现出一种平衡感与力量感的结合。她的头部微微抬起，目光直视前方，神情专注而坚定，仿佛在与观者进行无声的交流。整体姿态既展现了她在雪地中的从容不迫，又透露出一种时尚与自然融合的气质。背景中巍峨的雪山与晴朗的蓝天相映成趣，进一步衬托出她挺拔而优雅的身形。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 14:00:17\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 14:00:17', 6);
INSERT INTO `sys_oper_log` VALUES (365, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_52e23464-2de8-427e-8b5c-ad93d98dc44a_960x1280.png_width256.webp\",\"backWeId\":\"10000353137\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:55:48\",\"delFlag\":\"0\",\"id\":72,\"name\":\"bsd73\",\"params\":{},\"promot\":\"在这张图片中，模特以一种自信而从容的姿态站在雪地上。她的身体微微侧向画面左侧，头部略微转向镜头方向，目光坚定地望向前方，展现出一种沉稳与专注的神情。她的双臂自然下垂，右手轻轻握着一个黑色物品（可能是相机或滑雪装备），左手则拿着一个银色水杯，动作自然且不失优雅。双腿呈行走姿态，右腿在前，左腿稍后，呈现出动态的平衡感，仿佛正迈步前行。她的影子清晰地投射在身后雪地上，拉长的轮廓增强了画面的空间感和立体感。整体姿态流畅、协调，透露出一种在高山雪原中自由探索的洒脱与力量。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 14:00:23\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 14:00:23', 6);
INSERT INTO `sys_oper_log` VALUES (366, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_5279a5f3-c1d2-43cb-9183-edf5b08beec8_736x920.png_width256.webp\",\"backWeId\":\"10000353138\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:56:10\",\"delFlag\":\"0\",\"id\":73,\"name\":\"bsd74\",\"params\":{},\"promot\":\"模特站立在雪地中央，身体微微前倾，姿态自然放松。她的双臂自然垂于身侧，右手则拿着手机，手指戴着黑色手套，显得既保暖又时尚。她的头部略微低垂，目光朝向镜头方向，神情温柔而略带羞涩，展现出一种静谧的优雅感。整体姿态呈现出一种从容、沉静的氛围，与周围的雪景和木屋环境和谐相融，仿佛在享受冬日宁静的片刻。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 14:00:29\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 14:00:29', 5);
INSERT INTO `sys_oper_log` VALUES (367, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250919_1_7dd3d494-3f50-4696-828a-c91335bc8d9e_728x1280.png_width256.webp\",\"backWeId\":\"10000353139\",\"createBy\":\"\",\"createTime\":\"2025-09-19 13:56:33\",\"delFlag\":\"0\",\"id\":74,\"name\":\"bsd75\",\"params\":{},\"promot\":\"模特站在雪地上，双臂交叉抱在胸前，身体微微前倾，展现出一种自信而略带冷峻的姿态。她的站姿稳健，双脚略微分开，与地面形成稳固的支撑，显示出从容不迫的气场。头部微微扬起，目光直视镜头，透露出坚定与专注的神情。整体姿态呈现出一种既放松又充满力量的平衡感，仿佛在寒冷的环境中依然保持着内心的笃定与掌控力。背景是广阔的雪山和晴朗的蓝天，进一步衬托出她沉稳而独立的存在感。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-19 14:00:38\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-19 14:00:38', 5);
