INSERT INTO `sys_oper_log` VALUES (531, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250923_1_c6c80223-f50d-4beb-a98b-ce7eec95a345_1440x1920.png_width256.webp\",\"backWeId\":\"10000355973\",\"createBy\":\"\",\"createTime\":\"2025-09-23 18:33:43\",\"delFlag\":\"0\",\"id\":81,\"name\":\"bsd76\",\"params\":{},\"promot\":\"模特站在雪地上，身体微微前倾，重心略向前移，呈现出一种自然放松的姿态。她的双臂自然下垂，双手插在羽绒服的口袋中，显得随性而舒适。头部略微低垂，视线向下，神情专注而沉静，仿佛在凝视脚下的雪地或沉浸在自己的思绪中。双腿并拢站立，右脚稍向前踏出半步，形成一种微妙的动态平衡感。整体姿态展现出一种优雅与从容，既不过于僵硬，也不显随意，与周围的雪山和冬日环境融为一体，传递出一种宁静而坚定的气质。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-24 13:10:20\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-24 13:10:21', 39);
INSERT INTO `sys_oper_log` VALUES (532, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250923_1_f6d6e3a5-772f-45b9-b380-98e11dcdc348_1552x1920.png_width256.webp\",\"backWeId\":\"10000355974\",\"createBy\":\"\",\"createTime\":\"2025-09-23 18:34:52\",\"delFlag\":\"0\",\"id\":82,\"name\":\"bsd77\",\"params\":{},\"promot\":\"模特站立在雪地中，身体微微侧向画面左侧，头部略微转向镜头方向，展现出一种自然且从容的姿态。她的双臂自然地插在羽绒服的口袋中，身体保持直立，但略带放松感，呈现出一种既优雅又随性的气质。双腿并拢，脚跟轻触地面，重心稳定，整体姿态显得沉稳而自信。她微微抬起下巴，目光柔和地望向镜头，流露出一种宁静与淡然的情绪。背景中的雪松与积雪为她的姿态增添了冬日的静谧氛围，使整个画面更具层次感和视觉张力。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-24 13:10:30\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-24 13:10:30', 28);
INSERT INTO `sys_oper_log` VALUES (533, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250923_1_bb790aeb-2b8c-4163-86c8-50c9587d5115_1688x2048.png_width256.webp\",\"backWeId\":\"10000355976\",\"createBy\":\"\",\"createTime\":\"2025-09-23 18:36:05\",\"delFlag\":\"0\",\"id\":83,\"name\":\"bsd78\",\"params\":{},\"promot\":\"模特站在一片广阔的雪地上，背景是连绵起伏、覆盖着积雪的巍峨山脉。她身体微微侧向画面左侧，右腿稳稳地踩在雪地上，左腿高高抬起并伸向斜前方，脚尖自然点地，展现出一种轻盈而充满活力的姿态。她的双臂张开，右手向右侧伸展，左手则自然地放在身体一侧，仿佛在拥抱周围的壮丽景色。整个姿态显得自信、自由且富有动感，仿佛在与大自然互动，表达出一种无拘无束的喜悦和对高山雪景的热爱。她的身体线条流畅，动作舒展，呈现出一种平衡与力量的结合，既优雅又充满生命力。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-24 13:10:39\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-24 13:10:39', 21);
INSERT INTO `sys_oper_log` VALUES (534, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250923_1_9711555a-4f0a-4a08-90c8-1a761ad53c2b_1752x2048.png_width256.webp\",\"backWeId\":\"10000355977\",\"createBy\":\"\",\"createTime\":\"2025-09-23 18:36:30\",\"delFlag\":\"0\",\"id\":84,\"name\":\"bsd79\",\"params\":{},\"promot\":\"在这张图片中，模特站立在被厚厚积雪覆盖的白色铁艺栏杆前，姿态优雅而自然。她的身体微微侧向镜头，头部略微倾斜，目光直视前方，展现出一种从容与自信。她的左手轻抬至耳侧，手指轻轻触碰发丝，动作细腻而富有表现力，增添了一丝温柔与沉静的氛围。右臂自然下垂，整体姿势显得放松而不失端庄。双腿微微分开站立，重心稳定，呈现出一种既稳重又不失灵动的姿态。整个身体线条流畅，与周围雪景和谐相融，营造出一种静谧而唯美的视觉效果。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-24 13:10:49\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-24 13:10:49', 20);
INSERT INTO `sys_oper_log` VALUES (535, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250923_1_75586b7a-6ec9-4703-b4ed-09a72eaed995_1552x1920.png_width256.webp\",\"backWeId\":\"10000355978\",\"createBy\":\"\",\"createTime\":\"2025-09-23 18:36:54\",\"delFlag\":\"0\",\"id\":85,\"name\":\"bsd80\",\"params\":{},\"promot\":\"在这张图片中，模特以一种轻盈而舒展的姿态站立在广阔的雪原之上。她的身体微微侧向画面右侧，双臂自然地向两侧伸展，呈现出一种开放、自由的感觉。手臂的延伸仿佛在拥抱这片无垠的冰雪世界，展现出与自然融为一体的和谐感。她的左脚略微向前踏出，右脚稍后，形成一个动态的行走姿态，仿佛正迈步前行，又似在轻轻滑行于雪地上。腿部线条流畅，动作轻盈，显示出一种从容不迫的节奏感。整体姿态既具动感又不失优雅，仿佛在享受这片宁静天地中的片刻自由。她头部微微转向右侧，视线似乎投向远方的地平线，透露出一种探索与沉思的情绪。整个身体语言传达出一种对自然的敬畏与亲近，同时也流露出内心的平静与开阔。背景中辽阔的雪原和多云的天空进一步强化了这种孤独而又自由的氛围，使她的姿态显得更加突出与富有表现力。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-24 13:11:03\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-24 13:11:04', 26);
INSERT INTO `sys_oper_log` VALUES (536, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250923_1_4026c684-41f6-4a1a-88ae-d452d658f1d9_1632x2048.png_width256.webp\",\"backWeId\":\"10000355982\",\"createBy\":\"\",\"createTime\":\"2025-09-23 18:37:57\",\"delFlag\":\"0\",\"id\":86,\"name\":\"bsd81\",\"params\":{},\"promot\":\"模特站立在雪地上，身体微微侧向画面左侧，呈现出一种自然放松的姿态。她的左臂抬起，手轻轻搭在头盔边缘，似乎在调整或轻触头盔，动作显得优雅而随性。右臂自然下垂，手中稳稳地持着一块紫色的滑雪板，滑雪板斜靠在身体一侧，与身体形成一个流畅的线条。她的双腿略微分开，站姿稳健，重心均匀分布，展现出一种自信且从容的气质。整体姿态既充满运动感，又不失时尚与美感，仿佛在享受雪地中的宁静时刻。背景是连绵的雪山和苍翠的松树，衬托出她作为画面主体的突出存在感。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-24 13:11:26\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-24 13:11:27', 19);
INSERT INTO `sys_oper_log` VALUES (537, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250923_1_dd2a7e59-c613-4c11-bbae-b1f544a4cfa3_1568x2048.png_width256.webp\",\"backWeId\":\"10000355983\",\"createBy\":\"\",\"createTime\":\"2025-09-23 18:38:26\",\"delFlag\":\"0\",\"id\":87,\"name\":\"bsd82\",\"params\":{},\"promot\":\"在这张图片中，模特以一种自然、自信的姿态站立在雪地之中。她的身体略微朝向镜头，呈现出一种轻松而优雅的站姿。双臂自然下垂，，微微向外展开，展现出一种开放和欢迎的感觉。她的头部微微前倾，面带灿烂的笑容，眼神明亮，透露出愉悦与活力。她的姿势显得放松但不失端庄，仿佛正享受着眼前壮丽的雪山景色。整个姿态流露出一种从容不迫的气质，与背景中的直升机和雪山环境相得益彰，营造出一种高端、时尚且充满冒险气息的氛围。她似乎正准备开始一段滑雪之旅，或刚刚完成一次空中飞行，整体姿态传达出一种自由、自信与对自然美景的欣赏。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-24 13:11:57\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-24 13:11:57', 24);
