INSERT INTO `sys_oper_log` VALUES (612, '背景', 1, 'com.ruoyi.system.controller.WeBackController.add()', 'POST', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250925_1_db6b2727-6a59-475f-98cd-531e6fe42a3d_1656x2048.jpg_width256.webp\",\"backWeId\":\"10000357406\",\"createTime\":\"2025-09-25 16:37:43\",\"id\":113,\"name\":\"bsd92\",\"params\":{},\"promot\":\"在这张图片中，模特以一种极具张力和艺术感的姿态呈现。她蹲坐在雪地上，双腿弯曲并交叉，膝盖微微抬起，身体重心略微前倾，展现出一种既稳定又富有动态的平衡感。她的双手自然地放在膝盖上，戴着厚实的手套，手臂略向外展开，形成一种保护性的姿态，仿佛在与周围的寒冷环境进行互动。她的视线直视镜头，头部微微前倾，表情冷静而专注，透露出一种沉静的力量感。整个身体姿态呈现出一种低伏、收敛但不失力量的状态，仿佛在雪地中蓄势待发，准备迎接挑战。这种姿势不仅突出了她在极端环境中的适应能力，也营造出一种与自然融为一体的感觉。背景是巨大的雪块和蓝天，形成了强烈的视觉对比，进一步凸显了模特姿态的立体感和存在感。整体姿态传递出一种坚韧、独立与自然共存的气质。\",\"type\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-25 16:37:44', 109);
INSERT INTO `sys_oper_log` VALUES (613, '背景', 1, 'com.ruoyi.system.controller.WeBackController.add()', 'POST', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250925_1_0c2abb95-c42d-4f53-b37f-75d2cb8749b4_792x1272.jpg_width256.webp\",\"backWeId\":\"10000357411\",\"createTime\":\"2025-09-25 16:38:25\",\"id\":114,\"name\":\"bsd93\",\"params\":{},\"promot\":\"模特站立在湖边的石滩上，身体微微侧向画面右侧，头部略微低垂并转向右前方，目光柔和地望向远方。她的左手自然地抬起，轻轻搭在羽绒服的拉链处，手指轻触衣领边缘，姿态显得优雅而从容。右手则插在羽绒服的口袋中，身体线条放松但不失挺拔，整体呈现出一种静谧、沉思的氛围。背景是开阔的湖面与远处连绵起伏的山脉，天空湛蓝，云朵稀疏，衬托出她安静而独立的姿态。\",\"type\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-25 16:38:25', 16);
INSERT INTO `sys_oper_log` VALUES (614, '背景', 1, 'com.ruoyi.system.controller.WeBackController.add()', 'POST', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250925_1_501198ce-1ca5-40de-9ec6-d9ef417e5606_736x1104.jpg_width256.webp\",\"backWeId\":\"10000357412\",\"createTime\":\"2025-09-25 16:38:59\",\"id\":115,\"name\":\"bsd94\",\"params\":{},\"promot\":\"模特站立在户外的石质广场上，背景是一座古典风格的建筑，带有圆柱和雕花装饰。她身体微微侧向画面左侧，头部略微转向镜头方向，目光温和而自信地望向前方，嘴角带着自然的微笑，展现出一种轻松愉悦的情绪。她的双臂自然弯曲，双手交叠于胸前，右手轻搭在左手上，手指自然收拢，呈现出一种优雅而放松的姿态。整体站姿挺拔但不僵硬，双脚并拢，重心均匀分布，显得从容而稳重。她的姿态传达出一种既随性又不失精致的都市气质，仿佛在享受冬日里的一刻宁静与美好。\",\"type\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-25 16:38:59', 22);
INSERT INTO `sys_oper_log` VALUES (615, '背景', 1, 'com.ruoyi.system.controller.WeBackController.add()', 'POST', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250925_1_290023a2-4ab5-4882-ad39-5a57687c1cf3_736x904.jpg_width256.webp\",\"backWeId\":\"10000357414\",\"createTime\":\"2025-09-25 16:39:27\",\"id\":116,\"name\":\"bsd95\",\"params\":{},\"promot\":\"模特站在一片被白雪覆盖的湖边，背景是连绵起伏的雪山和清澈湛蓝的天空。她面向镜头，身体微微侧倾，姿态自然放松。她右手自然下垂。双腿略微分开，呈现出一种稳重而自信的站姿。她的头部微微前倾，目光直视镜头，展现出从容与优雅的气质。整体姿态显得既随性又充满力量感，与周围的自然景观形成和谐的对比。\",\"type\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-25 16:39:27', 23);
INSERT INTO `sys_oper_log` VALUES (616, '背景', 1, 'com.ruoyi.system.controller.WeBackController.add()', 'POST', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250925_1_dd41d270-af6c-4438-ab83-418ec7f3beba_1080x1328.jpg_width256.webp\",\"backWeId\":\"10000357415\",\"createTime\":\"2025-09-25 16:39:54\",\"id\":117,\"name\":\"bsd96\",\"params\":{},\"promot\":\"模特站立在雪地山巅之上，身体微微侧向画面右侧，双臂自然交叉抱于胸前，姿态显得沉静而自信。她的头部略微转向右侧，目光投向远方的山脉与湖景，神情专注而略带思索，仿佛在凝视着大自然的壮丽景色。整个姿态呈现出一种与自然融为一体的宁静感，既展现出对环境的敬畏，又流露出内心的平和与从容。站姿稳健，双脚并拢，重心均匀分布，显示出她在高海拔地形上的平衡与稳定。整体姿态传递出一种探索、欣赏与沉浸于自然之中的氛围。\",\"type\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-25 16:39:55', 18);
INSERT INTO `sys_oper_log` VALUES (617, '背景', 1, 'com.ruoyi.system.controller.WeBackController.add()', 'POST', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250925_1_89b8928d-1877-4e19-8477-fbf87d59f7cc_1536x2048.jpg_width256.webp\",\"backWeId\":\"10000357416\",\"createTime\":\"2025-09-25 16:40:29\",\"id\":118,\"name\":\"bsd97\",\"params\":{},\"promot\":\"模特正走在一条城市街道上，身体微微向右倾斜，呈现出自然行走的姿态。她的左臂自然下垂，显得轻松随意；右臂则略微弯曲，手中握着一杯咖啡，动作流畅而协调。她的头部略向右侧转动，目光望向画面右前方，神情专注而沉静，仿佛在观察周围的环境或思考着什么。整体姿态展现出一种从容、自信且不失优雅的都市女性形象，步伐稳健，节奏舒缓，与周围的城市背景融为一体，传递出一种日常生活中不经意的时尚感。\",\"type\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-25 16:40:30', 17);
