INSERT INTO `sys_oper_log` VALUES (647, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250926_1_d95c7994-153c-49db-a0d7-d51159548c7e_848x1280.jpg_width256.webp\",\"backWeId\":\"10000358128\",\"createBy\":\"\",\"createTime\":\"2025-09-26 13:31:07\",\"delFlag\":\"0\",\"id\":122,\"name\":\"bsd98\",\"params\":{},\"promot\":\"模特站在雪地上，身体微微侧向画面左侧，呈现出一种自然且自信的滑雪姿态。她的右腿略微向前伸展，左腿稍后，重心稳定地落在两脚之间，展现出良好的平衡感。右手握着滑雪杖，杖尖插入雪中，手臂自然下垂，带动身体形成流畅的线条。左手则自然地放在身侧，手指轻握滑雪杖的另一端，整体动作协调而放松。头部微微抬起，目光望向远方，透露出专注与从容的神情。背景是广阔的雪山和晴朗的蓝天，衬托出她动态中的静谧与力量感。整个姿态既体现了滑雪运动的专业性，又流露出优雅与从容的气质。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-26 13:53:31\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-26 13:53:31', 23);
INSERT INTO `sys_oper_log` VALUES (648, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250926_1_930e037a-45c8-495d-983f-bfe20c9d5a77_1080x1432.jpg_width256.webp\",\"backWeId\":\"10000358129\",\"createBy\":\"\",\"createTime\":\"2025-09-26 13:31:02\",\"delFlag\":\"0\",\"id\":121,\"name\":\"bsd99\",\"params\":{},\"promot\":\"模特站立在雪地之中，身体微微侧向画面左侧，右腿向前轻轻抬起，脚尖点地，呈现出一种轻盈而自然的动态姿态。她的左腿支撑身体重量，膝盖微屈，保持平衡。双臂自然下垂，左手插在羽绒服口袋中，右手则轻握滑雪杖，杖尖触地，略微倾斜，增强了整体的稳定感与运动气息。头部微微上扬，目光望向远方，展现出自信与从容的神情。整个姿态流畅、优雅，仿佛正准备开始一段雪地探险，既充满活力又不失从容。背景是连绵起伏的雪山和清澈的蓝天，衬托出她挺拔而坚定的身影。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-26 13:53:39\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-26 13:53:39', 17);
INSERT INTO `sys_oper_log` VALUES (649, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250926_1_b5712677-23d3-4055-bd29-764cb5264eb4_848x1280.jpg_width256.webp\",\"backWeId\":\"10000358130\",\"createBy\":\"\",\"createTime\":\"2025-09-26 13:38:36\",\"delFlag\":\"0\",\"id\":126,\"name\":\"bsd100\",\"params\":{},\"promot\":\"模特正走在城市街道上，身体微微前倾，步伐轻快而自信。她的头部略微转向一侧，目光投向画面左侧，似乎在观察周围的环境或与某人互动。双臂自然摆动，右手轻轻垂下，左手则自然地放在身侧。整体姿态展现出一种从容不迫的都市节奏感，仿佛在享受行走的过程，同时透露出一种随性而时尚的气质。背景中的车辆和建筑模糊处理，突出了她作为画面主体的动态存在感。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-26 13:53:49\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-26 13:53:49', 22);
INSERT INTO `sys_oper_log` VALUES (650, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250926_1_c2c62965-e9af-4dcb-89e1-cb1f9af67060_968x1200.jpg_width256.webp\",\"backWeId\":\"10000358131\",\"createBy\":\"\",\"createTime\":\"2025-09-26 13:38:32\",\"delFlag\":\"0\",\"id\":125,\"name\":\"bsd101\",\"params\":{},\"promot\":\"模特站立在雪地之中，身体微微向右侧倾斜，呈现出一种自然放松的姿态。她的双臂自然下垂，右手轻轻搭在身侧，左手则略微抬起，手掌朝向身体方向，仿佛在调整外套的边缘或保持平衡。她的头部微微上扬，目光望向画面左上方，展现出一种沉静而略带思索的神情。整体姿态优雅从容，与周围的雪景融为一体，传达出一种宁静、独立且充满力量的氛围。双腿并拢，站姿挺拔，显示出良好的体态控制和自信感。背景中的雪松与积雪进一步衬托出她静谧而坚定的存在感。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-26 13:53:57\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-26 13:53:57', 20);
INSERT INTO `sys_oper_log` VALUES (651, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250926_1_dc397d33-d1c7-41c5-9d2f-0f4211ee0d6c_952x1280.jpg_width256.webp\",\"backWeId\":\"10000358132\",\"createBy\":\"\",\"createTime\":\"2025-09-26 13:38:28\",\"delFlag\":\"0\",\"id\":124,\"name\":\"bsd102\",\"params\":{},\"promot\":\"模特站立在雪地中，身体微微侧向镜头，呈现出一种自然优雅的姿态。她的双臂自然垂放，左手则轻轻放在腹部前方，手指微微弯曲，显得从容而放松。她的头部略微倾斜，目光直视镜头，神情自信且略带微笑，流露出一种宁静与从容的气质。整体姿态舒展而平衡，展现出一种与雪景相融合的和谐美感。背景中的雪山和木屋为她的姿态增添了静谧而清冷的氛围，突显出她沉稳而优雅的气质。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-26 13:54:04\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-26 13:54:05', 17);
INSERT INTO `sys_oper_log` VALUES (652, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250926_1_afca39a3-84ed-4d8e-a804-cb9970406c2b_736x1304.jpg_width256.webp\",\"backWeId\":\"10000358133\",\"createBy\":\"\",\"createTime\":\"2025-09-26 13:38:23\",\"delFlag\":\"0\",\"id\":123,\"name\":\"bsd103\",\"params\":{},\"promot\":\"模特站立在雪地中，身体微微向右侧倾斜，姿态自然放松。她的双手轻轻搭在围巾的两端，左手稍高，右手略低，仿佛在调整或展示围巾的垂坠感。头部略微侧向镜头方向，视线直视前方，展现出一种从容自信的神情。整体姿态优雅而富有亲和力，与周围的雪景和建筑背景和谐相融，呈现出一种静谧而温暖的冬日氛围。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-09-26 13:54:13\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-09-26 13:54:14', 21);
