INSERT INTO `sys_oper_log` VALUES (685, '背景', 2, 'com.ruoyi.system.controller.WeBackController.edit()', 'PUT', 1, 'admin', NULL, '/back', '127.0.0.1', '', '{\"backUrl\":\"https://ai-image.weshop.com/20250911_1_39ec5c4b-746a-49c4-9a4d-8db455c313d1_744x1040.png_width256.webp\",\"backWeId\":\"10000346063\",\"createBy\":\"\",\"createTime\":\"2025-09-16 18:18:20\",\"delFlag\":\"0\",\"id\":11,\"name\":\"bsd48\",\"params\":{},\"promot\":\"在这张图片中，两位模特并肩站立在雪地背景前，姿态自然放松。左侧的模特身体略微侧向画面右侧，左手插在衣兜里，右手自然下垂，微微向前伸展。他的头部微微转向右侧，目光温和地注视着身旁的同伴，表情平和而亲切。右侧的模特则面向前方，身体略向左倾斜，与左侧模特形成一种互动的姿态。她的双手也自然地放在身体两侧，右臂稍向前伸，呈现出一种轻松的站姿。她的视线同样落在同伴身上，面带微笑，流露出一种温暖和谐的氛围。两人的站姿协调一致，彼此之间保持适当的距离，展现出一种默契与亲密感。整体姿态传达出一种轻松、愉悦的冬季出行场景，背景中的色彩鲜明的建筑也为画面增添了活泼的氛围。\",\"type\":\"1\",\"updateBy\":\"\",\"updateTime\":\"2025-10-10 13:11:56\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-10-10 13:11:56', 96);
INSERT INTO `sys_oper_log` VALUES (686, '外观', 2, 'com.ruoyi.system.controller.WeLookController.generateLooks()', 'POST', 1, 'admin', NULL, '/look/generateLooks', '127.0.0.1', '', '[167]', '{\"msg\":\"任务已提交，正在后台处理\",\"code\":200}', 0, NULL, '2025-10-10 13:12:09', 67);
