INSERT INTO `we_back` VALUES (46, 'bsd4', 'https://ai-image.weshop.com/20250911_1_2bbb454e-e189-4983-a1f5-d974ce7a4679_960x1280.png_width256.webp', '10000346005', '模特站立在雪地之中，身体微微侧向画面左侧，呈现出一种轻松自然的姿态。她的左腿向前抬起，脚尖轻轻点地，右腿则稳稳支撑身体，展现出一种动态的平衡感。她的双手自然地插在羽绒服的口袋中，左手微微握着一个黑色的小物件，可能是滑雪杖的把手，增添了一丝户外活动的气息。头部略微向右倾斜，面带微笑，目光看向画面右侧，流露出愉悦和自信的情绪。整体姿态既充满活力又不失优雅，仿佛正在享受雪山中的美好时光。', '1', '0', '', '2025-09-16 18:18:20', '', '2025-09-17 13:20:21', NULL);
