INSERT INTO `we_back` VALUES (64, 'bsd65', 'https://ai-image.weshop.com/20250919_1_cd0494e7-0e78-485b-bf77-17c028df0901_1024x1280.png_width256.webp', '10000353129', '在这张图片中，模特站在雪地上，背景是连绵的雪山和晴朗的蓝天。她的身体微微侧向镜头，呈现出一种自然且自信的姿态。她的一只手插在裤兜里，另一只手自然地垂在身侧，手中拿着滑雪护目镜，显得轻松而从容。她的双腿略微分开，站姿稳健，展现出良好的平衡感和对环境的掌控力。整体姿态既放松又充满活力，传达出一种享受户外运动的愉悦心情。', '1', '0', '', '2025-09-19 13:52:43', '', '2025-09-19 13:59:27', NULL);
