INSERT INTO `we_back` VALUES (86, 'bsd81', 'https://ai-image.weshop.com/20250923_1_4026c684-41f6-4a1a-88ae-d452d658f1d9_1632x2048.png_width256.webp', '10000355982', '模特站立在雪地上，身体微微侧向画面左侧，呈现出一种自然放松的姿态。她的左臂抬起，手轻轻搭在头盔边缘，似乎在调整或轻触头盔，动作显得优雅而随性。右臂自然下垂，手中稳稳地持着一块紫色的滑雪板，滑雪板斜靠在身体一侧，与身体形成一个流畅的线条。她的双腿略微分开，站姿稳健，重心均匀分布，展现出一种自信且从容的气质。整体姿态既充满运动感，又不失时尚与美感，仿佛在享受雪地中的宁静时刻。背景是连绵的雪山和苍翠的松树，衬托出她作为画面主体的突出存在感。', '1', '0', '', '2025-09-23 18:37:57', '', '2025-09-24 13:11:27', NULL);
